import pathlib,sys,hashlib
master=pathlib.Path(sys.argv[1]).read_text()
assert hashlib.sha256(master.encode()).hexdigest()=='efef3b342ff013d131b7aad343aef47d0eab8a0496213203d96c3e3d55852d5e','regional UI master changed'
assert master.count(' pristine=e.save_state()')==1
assert len(sys.argv)==5,'master ROM SAV output-directory'
out=pathlib.Path(sys.argv[4]).resolve();out.mkdir(parents=True,exist_ok=False)
prefix=master.split(' pristine=e.save_state()')[0]
sys.argv=[sys.argv[0],sys.argv[2],sys.argv[3]]
tail=" pristine=e.save_state()\n protected=[(e.sym('gPlayerParty'),600),(e.ptr('gSaveBlock1Ptr'),15720),(e.ptr('gSaveBlock2Ptr'),3876),(e.ptr('gPokemonStoragePtr'),33744)]\n protected_bytes=[e.read(p,n) for p,n in protected]\n arena=0;pages=[]\n try:\n  for n in range(1,152):call('GetSetPokedexFlag',n,2);call('GetSetPokedexFlag',n,3)\n  region(0);call('CB2_OpenPokedexFromStartMenu');wait('Task_PokedexScreen',6)\n  e.press('A');p=wait('Task_DexScreen_NumericalOrder',6)\n  tid=e.u8(p+65);lm=sy['gTasks']+40*tid+8\n  call('ListMenuChangeSelection',lm,1,40,1);e.run(24)\n  e.press('A');p=wait('Task_DexScreen_ShowMonPage',5)\n  assert call('SpeciesToNationalPokedexNum',e.u16(p+90))==41,'expected Zubat numerical row41'\n  sp=e.u16(p+90);e.press('A');p=wait('Task_DexScreen_ShowMonPage',9)\n  arena=call('Alloc',528);assert 0x02000000<=arena<0x0201c000,'marker QA heap allocation'\n  guards=b'HABITAT-QA-GUARD';assert len(guards)==16\n  e.write(arena,guards);e.write(arena+496,guards);e.write(arena+512,bytes(16))\n  mask=call('GetSpeciesPokedexAreaRegions',sp,arena+512);assert mask&7==7,('Zubat three region habitats',mask)\n  expected_counts={};visited=[];initial=e.u8(p+101)\n  for turn in range(4):\n   p=dex();r=e.u8(p+101);assert r in (0,1,2),'unexpected habitat region'\n   assert e.u16(p+90)==sp and task('Task_DexScreen_ShowMonPage') is not None and e.u8(p+1)==9\n   mark_tid=e.u8(p+4);assert mark_tid<16\n   ta=sy['gTasks']+40*mark_tid;assert e.u8(ta+4) and e.u32(ta)&~1==sy['Task_ShowAreaMarkers']\n   m=ta+8;buf=e.u32(m+8);assert buf==e.u32(m+4)\n   count=call('GetNumPokedexAreaMarkers',mark_tid);assert count==e.u8(m) and 0<count<=120,(r,count)\n   assert e.u16(buf-14)==0xa3a3 and e.u32(buf-12)>=480,'area marker heap buffer'\n   n=call('GetSpeciesPokedexAreaMarkers',sp,arena+16,r,e.u8(p+100))\n   assert n==count and e.read(arena+16,n*4)==e.read(buf,n*4),('rendered/native marker mismatch',r,n,count)\n   assert e.read(arena,16)==guards and e.read(arena+496,16)==guards,'marker buffer overflow'\n   sid=e.u8(m+13);assert sid<64\n   sprite=sy['gSprites']+68*sid;flags=e.u16(sprite+0x3e)\n   assert flags&1 and not(flags&4) and e.u32(sprite+0x18)==m,'hidden or invalid marker sprite'\n   marker_tasks=sum(bool(e.u8(sy['gTasks']+40*i+4)) and e.u32(sy['gTasks']+40*i)&~1==sy['Task_ShowAreaMarkers'] for i in range(16))\n   assert marker_tasks==1,'leaked marker tasks'\n   win=e.u8(p+74);wa=sy['gWindows']+12*win;wd=e.u8(wa+3);ht=e.u8(wa+4);pix=e.u32(wa+8)\n   assert 0<wd<=32 and 0<ht<=32 and 0x02000000<=pix<=0x02040000-wd*ht*32,'area map window bounds'\n   if turn<3:\n    assert r not in visited,'SELECT failed to visit three regions'\n    visited.append(r);e.shot(str(out/('habitat-region-%d.png'%r)))\n    row=dict(region=r,markers=count,marker_tasks=marker_tasks,map_window=[wd,ht],map_pixels_sha256=h(e.read(pix,wd*ht*32)))\n    pages.append(row);expected_counts[r]=count;emit('native_habitat_page',row)\n   else:assert r==initial and count==expected_counts[r],'SELECT cycle did not restore initial region'\n   if turn<3:e.press('SELECT');e.run(24)\n  assert set(visited)=={0,1,2}\n  assert len({x['map_pixels_sha256'] for x in pages})==3,'region map pixels not distinct'\n  egg=412\n  assert call('GetSpeciesPokedexAreaRegions',egg,arena+512)==0,'Egg unexpectedly has wild habitat'\n  for r in (0,1,2):assert call('GetSpeciesPokedexAreaMarkers',egg,arena+16,r,255)==0,('Egg marker',r)\n  assert e.read(arena,16)==guards and e.read(arena+496,16)==guards\n  call('Free',arena);arena=0\n  result=dict(pass_all=True,rom_sha256=h(rb),pages=pages,select_cycle=True,negative_egg_regions=3,temporary_native_ram_fixture=True,actual_device_fps_measured=False)\n finally:\n  e.load_state(pristine)\n  assert all(e.read(p,n)==v for (p,n),v in zip(protected,protected_bytes)),'native RAM Pokemon/save records not restored'\n  emit('original_runtime_records_restored',True)\nafter=saves();after[str(sav)]=h(sav.read_bytes());assert after==old,'original SAV changed';emit('original_saves_preserved',True)\n(out/'result.json').write_text(json.dumps(result,indent=2));emit('native_habitat_pages',result)\n"
exec(compile(prefix+tail,'native-habitat-pages','exec'))
